"""matplotlib.bezier — Bezier curve utilities."""

import numpy as _np


def get_intersection(cx1, cy1, cos_t1, sin_t1, cx2, cy2, cos_t2, sin_t2):
    """Return the intersection of two lines (each given by a point and a
    unit-tangent vector). Mirrors upstream's behaviour: solves the linear
    system for ``(t1, t2)`` and returns the resulting point. Falls back
    to the midpoint of the input centres when the lines are parallel."""
    # Line 1: (cx1, cy1) + t1 * (cos_t1, sin_t1)
    # Line 2: (cx2, cy2) + t2 * (cos_t2, sin_t2)
    # Solve: cx1 + t1*cos_t1 = cx2 + t2*cos_t2
    #        cy1 + t1*sin_t1 = cy2 + t2*sin_t2
    denom = cos_t1 * sin_t2 - sin_t1 * cos_t2
    if abs(denom) < 1e-12:
        # Parallel — return the midpoint of the two centres.
        return ((cx1 + cx2) * 0.5, (cy1 + cy2) * 0.5)
    dx, dy = cx2 - cx1, cy2 - cy1
    t1 = (dx * sin_t2 - dy * cos_t2) / denom
    return (cx1 + t1 * cos_t1, cy1 + t1 * sin_t1)


def get_normal_points(cx, cy, cos_t, sin_t, length):
    """Two points perpendicular to the (cos_t, sin_t) tangent, ``length``
    away on either side of (cx, cy)."""
    return ((cx - sin_t * length, cy + cos_t * length),
            (cx + sin_t * length, cy - cos_t * length))


def split_bezier_intersecting_with_closedpath(bezier, inside_closedpath,
                                                tolerance=0.01):
    """Bisect a Bezier path until each half lies entirely inside or
    entirely outside ``inside_closedpath``. Returns ``(inside_half,
    outside_half)`` matching upstream's signature."""
    bezier = list(bezier)
    # de Casteljau subdivision via the BezierSegment helper.
    seg = BezierSegment(bezier)
    t = find_bezier_t_intersecting_with_closedpath(
        seg.point_at_t, inside_closedpath, tolerance=tolerance)
    # Build the two halves by point-sampling at t.
    n = len(bezier)
    left = [seg.point_at_t(t * i / max(1, n - 1)) for i in range(n)]
    right = [seg.point_at_t(t + (1 - t) * i / max(1, n - 1)) for i in range(n)]
    if inside_closedpath(left[0]):
        return left, right
    return right, left


def find_bezier_t_intersecting_with_closedpath(bezier_point_at_t,
                                                  inside_closedpath,
                                                  t0=0., t1=1.,
                                                  tolerance=0.01):
    """Binary-search the parameter ``t`` ∈ [t0, t1] at which the Bezier
    curve crosses ``inside_closedpath``'s boundary."""
    in0 = inside_closedpath(bezier_point_at_t(t0))
    in1 = inside_closedpath(bezier_point_at_t(t1))
    if in0 == in1:
        # No crossing in this range — return midpoint as best effort.
        return (t0 + t1) * 0.5
    while (t1 - t0) > tolerance:
        tm = (t0 + t1) * 0.5
        in_m = inside_closedpath(bezier_point_at_t(tm))
        if in_m == in0:
            t0 = tm
        else:
            t1 = tm
    return (t0 + t1) * 0.5


class BezierSegment:
    def __init__(self, control_points):
        self._cpoints = _np.asarray(control_points)

    def point_at_t(self, t):
        n = len(self._cpoints) - 1
        result = _np.zeros(2)
        for i, cp in enumerate(self._cpoints):
            b = _comb(n, i) * (1 - t)**(n - i) * t**i
            result += b * cp
        return tuple(result)

    @property
    def control_points(self):
        return self._cpoints


def _comb(n, k):
    from math import factorial
    return factorial(n) // (factorial(k) * factorial(n - k))


def make_wedge_fly(x, y, w, h, theta1, theta2, n=50):
    """Build an ``n``-point polyline approximating a wedge arc centred
    at ``(x, y)`` with axes ``(w, h)``, spanning ``theta1..theta2`` in
    degrees. Returns an ``(n, 2)`` numpy array."""
    t = _np.linspace(_np.radians(theta1), _np.radians(theta2), int(n))
    return _np.column_stack([x + w * _np.cos(t),
                              y + h * _np.sin(t)])


