class NonIntersectingPathException(ValueError):
    """Raised when a path was expected to intersect another shape but
    doesn't. Used internally by split_path_inout."""
    pass


def get_cos_sin(x0, y0, x1, y1):
    """Return (cos(θ), sin(θ)) where θ is the angle of the segment
    (x0, y0)→(x1, y1). If the segment is degenerate (zero length),
    returns (0.0, 0.0)."""
    dx, dy = x1 - x0, y1 - y0
    d = (dx * dx + dy * dy) ** 0.5
    if d == 0:
        return 0.0, 0.0
    return dx / d, dy / d


def check_if_parallel(dx1, dy1, dx2, dy2, tolerance=1.0e-5):
    """Return 1, 0, or -1 depending on whether the two direction
    vectors are parallel (same sign), anti-parallel (opposite sign),
    or non-parallel.

    Uses the cross-product magnitude scaled by each vector's length
    so the tolerance is rotation-invariant.
    """
    cross = dx1 * dy2 - dx2 * dy1
    n1 = (dx1 * dx1 + dy1 * dy1) ** 0.5
    n2 = (dx2 * dx2 + dy2 * dy2) ** 0.5
    if n1 == 0 or n2 == 0:
        return 1
    if abs(cross) > tolerance * n1 * n2:
        return 0
    # Parallel — same direction if the dot product is positive.
    dot = dx1 * dx2 + dy1 * dy2
    return 1 if dot >= 0 else -1


def inside_circle(cx, cy, r):
    """Return a predicate ``f(xy)`` that tells whether the point ``xy``
    (a 2-tuple) lies inside the circle centred at ``(cx, cy)`` with
    radius ``r``. Used by split_path_inout as the closed-path test.
    """
    r2 = r * r
    def _inside(xy):
        dx = xy[0] - cx
        dy = xy[1] - cy
        return dx * dx + dy * dy < r2
    return _inside


def split_de_casteljau(beta, t):
    """Split a Bezier curve at parameter ``t`` using de Casteljau's
    algorithm. ``beta`` is the array of control points; returns the
    two new control-point arrays ``(left, right)`` whose curves
    concatenate to the original.

    Works for any degree (the algorithm doesn't care).
    """
    arr = _np.asarray(beta, dtype=float)
    left = [arr[0].copy()]
    right = [arr[-1].copy()]
    current = arr.copy()
    while len(current) > 1:
        new = (1 - t) * current[:-1] + t * current[1:]
        left.append(new[0].copy())
        right.append(new[-1].copy())
        current = new
    right.reverse()
    return _np.asarray(left), _np.asarray(right)


def split_path_inout(path, inside, tolerance=0.01, reorder_inout=False):
    """Find the first place where ``path`` crosses the boundary of
    the region defined by ``inside`` (a predicate) and split the path
    there. Returns the two halves as ``(path_in, path_out)``.

    Uses a binary search on the segments. If the path never crosses
    the boundary, raises ``NonIntersectingPathException``.
    """
    verts = _np.asarray(getattr(path, 'vertices', path))
    if len(verts) < 2:
        raise NonIntersectingPathException("path has fewer than two vertices")

    inside_first = inside(verts[0])
    for i in range(1, len(verts)):
        if inside(verts[i]) != inside_first:
            # Found the segment that crosses the boundary; binary-
            # search to the tolerance.
            p0, p1 = verts[i - 1], verts[i]
            lo, hi = 0.0, 1.0
            while hi - lo > tolerance:
                mid = (lo + hi) * 0.5
                mid_pt = p0 + (p1 - p0) * mid
                if inside(mid_pt) == inside_first:
                    lo = mid
                else:
                    hi = mid
            t_cross = (lo + hi) * 0.5
            split_pt = p0 + (p1 - p0) * t_cross
            first = _np.vstack([verts[:i], [split_pt]])
            second = _np.vstack([[split_pt], verts[i:]])
            return first, second
    raise NonIntersectingPathException("path does not cross the boundary")


def find_control_points(c1x, c1y, mmx, mmy, c2x, c2y):
    """Given three points on a quadratic Bezier curve — the start,
    the curve point at t=0.5, and the end — recover the control point
    that produces that curve.

    For a quadratic Bezier, ``B(0.5) = 0.25*P0 + 0.5*P1 + 0.25*P2``,
    so ``P1 = 2*B(0.5) - 0.5*(P0 + P2)``. Returns ``[(c1x, c1y),
    (cmx, cmy), (c2x, c2y)]``.
    """
    cmx = 2.0 * mmx - 0.5 * (c1x + c2x)
    cmy = 2.0 * mmy - 0.5 * (c1y + c2y)
    return [(c1x, c1y), (cmx, cmy), (c2x, c2y)]


def get_parallels(bezier2, width):
    """For a quadratic Bezier control polygon ``[(x0, y0), (x1, y1),
    (x2, y2)]``, return two parallel control polygons offset by
    ``width / 2`` to the left and right of the curve.

    The offset direction at each endpoint is the perpendicular of the
    tangent at that endpoint. The middle control point of the parallel
    is recovered via :func:`find_control_points` from the offset
    endpoints and the offset midpoint.
    """
    (c1x, c1y), (cmx, cmy), (c2x, c2y) = (
        bezier2[0], bezier2[1], bezier2[2])
    # Tangents at each endpoint (start → mid, mid → end).
    cos1, sin1 = get_cos_sin(c1x, c1y, cmx, cmy)
    cos2, sin2 = get_cos_sin(cmx, cmy, c2x, c2y)
    # Endpoint offsets — perpendicular to each tangent.
    h = width * 0.5
    c1x_l, c1y_l = c1x - sin1 * h, c1y + cos1 * h
    c1x_r, c1y_r = c1x + sin1 * h, c1y - cos1 * h
    c2x_l, c2y_l = c2x - sin2 * h, c2y + cos2 * h
    c2x_r, c2y_r = c2x + sin2 * h, c2y - cos2 * h
    # Curve midpoint — sample the quadratic at t=0.5.
    mid_x = 0.25 * c1x + 0.5 * cmx + 0.25 * c2x
    mid_y = 0.25 * c1y + 0.5 * cmy + 0.25 * c2y
    # Average the two endpoint tangents for the midpoint perpendicular.
    avg_cos = (cos1 + cos2) * 0.5
    avg_sin = (sin1 + sin2) * 0.5
    norm = (avg_cos * avg_cos + avg_sin * avg_sin) ** 0.5 or 1.0
    avg_cos /= norm; avg_sin /= norm
    mid_x_l, mid_y_l = mid_x - avg_sin * h, mid_y + avg_cos * h
    mid_x_r, mid_y_r = mid_x + avg_sin * h, mid_y - avg_cos * h
    left = find_control_points(c1x_l, c1y_l, mid_x_l, mid_y_l,
                                c2x_l, c2y_l)
    right = find_control_points(c1x_r, c1y_r, mid_x_r, mid_y_r,
                                 c2x_r, c2y_r)
    return left, right


def make_wedged_bezier2(bezier2, width, w1=1.0, wm=0.5, w2=0.0):
    """Like :func:`get_parallels` but with the offset width tapering
    smoothly along the curve: ``w1`` at the start, ``wm`` at the
    middle, ``w2`` at the end. Returns ``(left, right)`` control
    polygons of the wedge.
    """
    left_w1, right_w1 = get_parallels(bezier2, width * w1)
    left_wm, right_wm = get_parallels(bezier2, width * wm)
    left_w2, right_w2 = get_parallels(bezier2, width * w2)
    left = find_control_points(left_w1[0][0], left_w1[0][1],
                                left_wm[1][0], left_wm[1][1],
                                left_w2[2][0], left_w2[2][1])
    right = find_control_points(right_w1[0][0], right_w1[0][1],
                                 right_wm[1][0], right_wm[1][1],
                                 right_w2[2][0], right_w2[2][1])
    return left, right


# ─── Added: BezierSegment introspection ─────────────────────────────


@property
def _bs_degree(self):
    return len(self._cpoints) - 1
BezierSegment.degree = _bs_degree

@property
def _bs_dimension(self):
    return self._cpoints.shape[1] if self._cpoints.ndim > 1 else 1
BezierSegment.dimension = _bs_dimension

def _bs_axis_aligned_extrema(self):
    """Return ``(dims, extrema_t)`` — the parameters where the curve
    reaches its extrema along each axis. Computed from the polynomial
    coefficients."""
    import numpy as _np
    coefs = self.polynomial_coefficients
    n = self.degree
    if n < 1:
        return _np.array([]), _np.array([])
    # Derivative coefficients.
    d_coefs = coefs[1:] * _np.arange(1, n + 1)[:, None]
    dims = []
    ts = []
    for d in range(coefs.shape[1]):
        c = d_coefs[:, d]
        if not _np.any(c):
            continue
        roots = _np.roots(c[::-1])
        for r in roots:
            if _np.isreal(r):
                t = float(r.real)
                if 0 <= t <= 1:
                    dims.append(d)
                    ts.append(t)
    return _np.array(dims), _np.array(ts)
BezierSegment.axis_aligned_extrema = _bs_axis_aligned_extrema

@property
def _bs_polynomial_coefficients(self):
    """Compute the polynomial coefficients (in power form) from the
    Bezier control points. ``coefs[i, j]`` is the coefficient of t^i
    along dimension j."""
    import numpy as _np
    n = self.degree
    pts = self._cpoints
    # Bernstein → power basis: c_i = Σ_j (-1)^(i-j) C(n, i) C(i, j) p_j
    import math
    coefs = _np.zeros_like(pts, dtype=float)
    for i in range(n + 1):
        for j in range(i + 1):
            coefs[i] += ((-1) ** (i - j)) * math.comb(n, i) * math.comb(i, j) * pts[j]
    return coefs
BezierSegment.polynomial_coefficients = _bs_polynomial_coefficients
